def read_jsonl(path):
    with open(path) as f:
        return [json.loads(line) for line in f if line.strip()]

def to_mono_16k(wave, sr):
    wave = wave.mean(axis=0)
    return librosa.resample(wave, orig_sr=sr, target_sr=16000)

def top_k(scores, k):
    idx = np.argpartition(-scores, k)[:k]
    return idx[np.argsort(-scores[idx])]

def sample_frames(container, fps=1.0):
    step = round(container.streams.video[0].average_rate / fps)
    return [f.to_image() for i, f in enumerate(container.decode(video=0)) if i % step == 0]
